test('QQ logged-in and core-ready are distinct; explicit QR refresh is not repeated by normal polling',async t=>{
  const f=await fixture(t),first=await startReady(f),args={instanceId:'persona-a',flowId:first.flowId};await f.service.poll(args);assert.equal(f.counts.refresh,0);const refreshed=await f.service.poll({...args,refreshQr:true});assert.match(refreshed.qrContent,/refreshed/);assert.equal(f.counts.refresh,1);
  f.setInitializing(true);const pending=await f.service.poll({...args,refreshQr:true});assert.equal(pending.phase,'waiting_login');assert.equal(pending.qrContent,null);assert.equal(pending.loginPhase,'initializing');assert.match(pending.progressMessage,/核心/);assert.equal(f.counts.getQr,0);assert.equal(f.counts.refresh,1);
  f.setInitializing(false);const authorized=await f.service.poll(args);assert.equal(authorized.phase,'authorized');assert.deepEqual(authorized.loginAccount,{accountId:'12345678',displayName:'fixture'});assert.equal(authorized.connected,false);
});

test('an expired QR manual refresh uses a new read status rather than retaining the previous login error',async t=>{
  const f=await fixture(t),first=await startReady(f),args={instanceId:'persona-a',flowId:first.flowId};f.setLoginError('二维码已经过期，请刷新二维码');const expired=await f.service.poll(args);assert.equal(expired.error.code,'NAPCAT_LOGIN_ERROR');assert.equal(expired.management.status,'ready');const before=f.requests.filter(value=>value.route==='/api/QQLogin/CheckLoginStatus').length;
  f.setFetchHook(async url=>{if(url.endsWith('/RefreshQRcode'))f.setLoginError(null);});const fresh=await f.service.poll({...args,refreshQr:true});assert.match(fresh.qrContent,/refreshed/);assert.equal(fresh.error,null);assert.equal(fresh.phase,'waiting_login');assert.equal(fresh.qrLoginAccepted,false);assert.equal(fresh.lastVerifiedQQ.online,false);assert.equal(fresh.loginAccount,null);assert.equal(f.counts.refresh,1);assert.equal(f.counts.spawn,1);assert.equal(f.requests.filter(value=>value.route==='/api/QQLogin/CheckLoginStatus').length,before+2);
  await f.service.poll(args);assert.equal(f.counts.refresh,1,'ordinary checks do not rotate again');
});

test('QR refresh keeps a genuinely new login error and recognizes confirmation received during the refresh',async t=>{
  const f=await fixture(t),first=await startReady(f),args={instanceId:'persona-a',flowId:first.flowId};f.setLoginError('old expired QR');await f.service.poll(args);
  f.setFetchHook(async url=>{if(url.endsWith('/RefreshQRcode'))f.setLoginError('new login validation failure #2132');});const failed=await f.service.poll({...args,refreshQr:true});assert.equal(failed.error.code,'NAPCAT_LOGIN_ERROR');assert.match(failed.error.message,/new login validation failure/);assert.doesNotMatch(failed.error.message,/old expired/);assert.equal(failed.connected,false);
  f.setFetchHook(async url=>{if(url.endsWith('/RefreshQRcode')){f.setLoginError(null);f.setAccepted(true);}});const confirmed=await f.service.poll({...args,refreshQr:true});assert.equal(confirmed.error,null);assert.equal(confirmed.phase,'waiting_login');assert.equal(confirmed.qrLoginAccepted,true);assert.equal(confirmed.qrContent,null);assert.match(confirmed.progressMessage,/手机已确认/);assert.equal(confirmed.connected,false);assert.equal(f.counts.refresh,2);
});

test('explicit QR regeneration never runs for scanned, initializing, reconnecting or generating statuses',async t=>{
  const f=await fixture(t),first=await startReady(f),args={instanceId:'persona-a',flowId:first.flowId};
  for(const loginPhase of ['qrcode_scanned','initializing','online','reconnecting','generating_qrcode']){f.setFetchHook(async url=>url.endsWith('/CheckLoginStatus')?Response.json({code:0,data:{isLogin:false,coreReady:false,qrLoginAccepted:false,loginPhase,qrcodeurl:'https://ntlogin.qq.com/old',loginError:null}}):null);const current=await f.service.poll({...args,refreshQr:true});assert.equal(current.qrContent,null,loginPhase);assert.equal(f.counts.refresh,0,loginPhase);}
  f.setFetchHook(null);f.setAccepted(true);await f.service.poll({...args,refreshQr:true});assert.equal(f.counts.refresh,0);f.setAccepted(false);f.setInitializing(true);await f.service.poll({...args,refreshQr:true});assert.equal(f.counts.refresh,0);
});

test('a manual QR mutation cannot bypass unavailable management or issue another login during cooldown',async t=>{
  const f=await fixture(t),first=await startReady(f),args={instanceId:'persona-a',flowId:first.flowId};f.setFetchHook(async url=>{if(url.endsWith('/CheckLoginStatus'))throw Object.assign(new Error('isolated offline'),{code:'ECONNREFUSED'});});const unavailable=await f.service.poll(args);assert.equal(unavailable.management.status,'unavailable');f.setFetchHook(null);const before=f.requests.length;const unchanged=await f.service.poll({...args,refreshQr:true});assert.equal(unchanged.management.status,'unavailable');assert.equal(f.requests.length,before);assert.equal(f.counts.refresh,0);
  await f.service.poll(args);f.setFetchHook(async url=>url.endsWith('/CheckLoginStatus')?Response.json({code:-1,message:'Unauthorized'}):url.endsWith('/auth/login')?Response.json({code:-1,message:'login rate limit'}):null);const limited=await f.service.poll(args);assert.equal(limited.management.status,'rate_limited');const requests=f.requests.length;await f.service.poll({...args,refreshQr:true});assert.equal(f.requests.length,requests);assert.equal(f.counts.refresh,0);
});

