async function offlineWithoutQr(f){f.logOut();f.setFetchHook(async url=>{
 if(url.endsWith('/CheckLoginStatus'))return Response.json({code:0,data:{isLogin:false,coreReady:false,loginPhase:'offline',qrLoginAccepted:false,qrcodeurl:'',loginError:'QQ login expired; isolated restart unavailable'}});
 if(url.endsWith('/GetQQLoginQrcode'))return Response.json({code:-1,message:'QRCode Get Error'});
});const current=await f.service.inspect();return f.service.poll({instanceId:'persona-a',flowId:current.flowId});}
async function waitManagedLaunch(f){let value;for(let i=0;i<5000;i++){value=await f.service.inspect();if(value.phase!=='installing')break;await tick();}assert.notEqual(value.phase,'installing');return value;}

